    if (!activeDays.has(cursor.toISOString().slice(0, 10))) cursor.setDate(cursor.getDate() - 1);
    while(activeDays.has(cursor.toISOString().slice(0, 10))){
        streak += 1;
        cursor.setDate(cursor.getDate() - 1);
    }
